Method.Source:
/// <summary>
/// Delegate for state change event.
/// </summary>
/// <param name="_newState">The new state of the cash sales desk.</param>
delegate void stateChanged(AVARUMCashSalesDeskState _newState)
{
}

/// <summary>
/// Indicates if the cash sales desk is open.
/// </summary>
/// <returns>true if the cash sales desk is open, otherwise false</returns>
[SysClientCacheDataMethodAttribute(true)]
public display AVARUMCashSalesDeskIsOpen IsOpen()
{
    return this.State == AVARUMCashSalesDeskState::Open;
}

/// <summary>
/// Gets the opening date of the cash sales desk.
/// </summary>
/// <returns>The opening date of the cash sales desk.</returns>    
[SysClientCacheDataMethodAttribute(true)]
public display TransDate openAtAsDate()
{
    return DateTimeUtil::date(this.OpenAt);
}

/// <summary>
/// Indicates if the cash sales desk is closed.
/// </summary>
/// <returns>true if the cash sales desk is closed, otherwise false</returns>
[SysClientCacheDataMethodAttribute(true)]
public display AVARUMCashSalesDeskIsClosed IsClosed()
{
    return this.State == AVARUMCashSalesDeskState::Closed;
}

/// <summary>
/// Gets the closing date of the cash sales desk.
/// </summary>
/// <returns>The closing date of the cash sales desk.</returns>
[SysClientCacheDataMethodAttribute(true)]
public display TransDate ClosedAtAsDate()
{
    return DateTimeUtil::date(this.ClosedAt);
}

/// <summary>
/// Finds a cash sales desk record by its ID.
/// </summary>
/// <param name="_id">The ID of the cash sales desk.</param>
/// <param name="_selectForUpdate">Indicates if the record should be selected for update.</param>
/// <returns>The cash sales desk record.</returns>
public static AVARUMCashSalesDesk find(AVARUMCashSalesDeskId _id, boolean _selectForUpdate = false)
{
    AVARUMCashSalesDesk cashDesk;

    select firstOnly cashDesk
        where cashDesk.Id == _id;

    cashDesk.selectForUpdate(_selectForUpdate);

    return cashDesk;
}

/// <summary>
/// Checks if a cash sales desk record exists by its ID.
/// </summary>
/// <param name="_id">The ID of the cash sales desk.</param>
/// <returns>True if the cash sales desk record exists, otherwise false.</returns>
public static boolean exist(AVARUMCashSalesDeskId _id)
{
    AVARUMCashSalesDesk cashDesk;

    select firstOnly RecId from cashDesk
    where cashDesk.Id == _id;

    return cashDesk.RecId != 0;
}

/// <summary>
/// Finds a cash sales desk record by its RecId.
/// </summary>
/// <param name="_recId">The RecId of the cash sales desk.</param>
/// <param name="_selectForUpdate">Indicates if the record should be selected for update.</param>
/// <returns>The cash sales desk record.</returns>
public static AVARUMCashSalesDesk findByRecId(AVARUMCashSalesDeskRefRecId _recId, boolean _selectForUpdate)
{
    AVARUMCashSalesDesk cashDesk;

    select firstOnly cashDesk
        where cashDesk.RecId == _recId;

    cashDesk.selectForUpdate(_selectForUpdate);

    return cashDesk;
}

/// <summary>
/// Sets the cash sales desk to closed.
/// </summary>
/// <param name="_refRecid">The RecId of the cash sales desk.</param>
/// <param name="_amount">The amount to set.</param>
/// <returns>true if the operation was successful, otherwise false</returns>
public static boolean setClose
(
    AVARUMCashSalesDeskRefRecId _refRecid,
    AVARUMCashSalesDeskAmount _amount
    //RUMCashBoxBalance _cashBoxBalance
    )
{
    AVARUMCashSalesDesk cashDesk;

    cashDesk = AVARUMCashSalesDesk::findByRecId(_refRecid, true);

    if (!cashDesk)
    {
        return false;
    }

    cashDesk.Amount = _amount;

    return cashDesk.close();
}

