/// <summary>
/// Opens the cash sales desk.
/// </summary>
/// <returns>true if the operation was successful, otherwise false</returns>
public boolean open()
{
    //RUMCashBoxBalance   cashBoxBalance;

    ttsbegin;

    this.selectForUpdate(true);
    this.State = AVARUMCashSalesDeskState::Open;
    this.OpenAt = DateTimeUtil::utcNow();
    this.ClosedAt = Global::utcDateTimeNull();
    this.update();

    //cashBoxBalance = RUMCashBoxBalance::initFromCashBox(this);

    ttscommit;

    return true;
}

/// <summary>
/// Provides a lookup for the cash sales desk.
/// </summary>
/// <param name="_control">The form control to attach the lookup to.</param>
public static void lookup(FormStringControl _control)
{
    SysTableLookup sysTableLookup;
    QueryBuildDataSource qbds;
    Query query;

    sysTableLookup = SysTableLookup::newParameters(tablenum(AVARUMCashSalesDesk), _control);

    query = new Query();
    qbds = query.addDataSource(tablenum(AVARUMCashSalesDesk));
    sysTableLookup.parmQuery(query);

    sysTableLookup.addLookupfield(fieldNum(AVARUMCashSalesDesk, Id), true);
    sysTableLookup.addLookupfield(fieldNum(AVARUMCashSalesDesk, Name));
    sysTableLookup.addLookupfield(fieldNum(AVARUMCashSalesDesk, State));
    sysTableLookup.addLookupfield(fieldNum(AVARUMCashSalesDesk, Amount));

    sysTableLookup.performFormLookup();
}

/// <summary>
/// Initializes the cash sales desk record.
/// </summary>
public void initValue()
{
    super();

    this.State = AVARUMCashSalesDeskState::Closed;
}

/// <summary>
/// Updates the record.
/// </summary>
public void update()
{
    boolean isStateChanged = this.orig().State != this.State;

    super();

    if (isStateChanged)
    {
        this.stateChanged(this.State);
    }
}

/// <summary>
/// Determines if closing the cash sales desk is required.
/// </summary>
/// <returns>True if closing is required, otherwise false.</returns>
public boolean isCloseRequired()
{
    boolean isRequired;

    isRequired =
    (
        this.State == AVARUMCashSalesDeskState::Open &&
        DateTimeUtil::date(this.OpenAt) != DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()) &&
        this.ClosedAt == Global::utcDateTimeNull()
    );
    if (isRequired)
    {
        warning(strFmt("@AVARUM:CashSalesDeskCloseRequired", this.openAtAsDate()));
        isRequired=false;
    }

    return isRequired;
}
